package com.moodtools.hub

internal object LauncherTranslationChunk5 {
    val entries = mapOf(
        "Launcher release history is unavailable. Add-on changes shown below are still verified from the catalog." to arrayOf("Hindi magagamit ang kasaysayan ng release ng launcher. Ang mga pagbabago sa add-on na ipinapakita sa ibaba ay verified pa rin mula sa katalogo.", "\uB7F0\uCC98 \uB9B4\uB9AC\uC2A4 \uAE30\uB85D\uC744 \uC0AC\uC6A9\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4. \uC544\uB798\uC5D0 \uD45C\uC2DC\uB41C \uC560\uB4DC\uC628 \uBCC0\uACBD \uC0AC\uD56D\uC740 \uC5EC\uC804\uD788 \uCE74\uD0C8\uB85C\uADF8\uC5D0\uC11C \uAC80\uC99D\uB418\uC5C8\uC2B5\uB2C8\uB2E4.", "\u30E9\u30F3\u30C1\u30E3\u30FC\u306E\u30EA\u30EA\u30FC\u30B9\u5C65\u6B74\u306F\u5229\u7528\u3067\u304D\u307E\u305B\u3093\u3002\u4EE5\u4E0B\u306B\u793A\u3059\u30A2\u30C9\u30AA\u30F3\u306E\u5909\u66F4\u306F\u5F15\u304D\u7D9A\u304D\u30AB\u30BF\u30ED\u30B0\u304B\u3089\u691C\u8A3C\u6E08\u307F\u3067\u3059\u3002", "\u542F\u52A8\u5668\u7248\u672C\u5386\u53F2\u4E0D\u53EF\u7528\u3002\u4E0B\u65B9\u663E\u793A\u7684\u9644\u52A0\u7EC4\u4EF6\u66F4\u6539\u4ECD\u5DF2\u4ECE\u76EE\u5F55\u9A8C\u8BC1\u3002", "El historial de versiones del launcher no est\u00E1 disponible. Los cambios de complementos mostrados a continuaci\u00F3n todav\u00EDa est\u00E1n verificados desde el cat\u00E1logo.", "L\u1ECBch s\u1EED ph\u00E1t h\u00E0nh c\u1EE7a launcher kh\u00F4ng kh\u1EA3 d\u1EE5ng. C\u00E1c thay \u0111\u1ED5i ph\u1EE5 tr\u1EE3 hi\u1EC3n th\u1ECB d\u01B0\u1EDBi \u0111\u00E2y v\u1EABn \u0111\u01B0\u1EE3c x\u00E1c minh t\u1EEB danh m\u1EE5c.", "Riwayat rilis peluncur tidak tersedia. Perubahan add-on yang ditampilkan di bawah masih diverifikasi dari katalog.", "O hist\u00F3rico de vers\u00F5es do lan\u00E7ador n\u00E3o est\u00E1 dispon\u00EDvel. As altera\u00E7\u00F5es do complemento mostradas abaixo ainda s\u00E3o verificadas pelo cat\u00E1logo."),
        "Launcher session couldn't be verified" to arrayOf("Hindi makumpirma ang sesyon ng Launcher", "\uB7F0\uCC98 \uC138\uC158\uC744 \uD655\uC778\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4", "\u30E9\u30F3\u30C1\u30E3\u30FC\u30BB\u30C3\u30B7\u30E7\u30F3\u3092\u78BA\u8A8D\u3067\u304D\u307E\u305B\u3093\u3067\u3057\u305F", "\u542F\u52A8\u5668\u4F1A\u8BDD\u65E0\u6CD5\u9A8C\u8BC1", "No se pudo verificar la sesi\u00F3n del lanzador", "Phi\u00EAn kh\u1EDFi ch\u1EA1y kh\u00F4ng th\u1EC3 \u0111\u01B0\u1EE3c x\u00E1c minh", "Sesi peluncur tidak dapat diverifikasi", "Sess\u00E3o do Launcher n\u00E3o p\u00F4de ser verificada"),
        "Launcher update cancelled" to arrayOf("Kanselado ang pag-update ng Launcher", "\uB7F0\uCC98 \uC5C5\uB370\uC774\uD2B8\uAC00 \uCDE8\uC18C\uB418\uC5C8\uC2B5\uB2C8\uB2E4", "\u30E9\u30F3\u30C1\u30E3\u30FC\u306E\u66F4\u65B0\u304C\u30AD\u30E3\u30F3\u30BB\u30EB\u3055\u308C\u307E\u3057\u305F", "\u542F\u52A8\u5668\u66F4\u65B0\u5DF2\u53D6\u6D88", "Actualizaci\u00F3n del lanzador cancelada", "C\u1EADp nh\u1EADt tr\u00ECnh kh\u1EDFi ch\u1EA1y \u0111\u00E3 b\u1ECB h\u1EE7y", "Pembaruan peluncur dibatalkan", "Atualiza\u00E7\u00E3o do Launcher cancelada"),
        "Launcher update check failed" to arrayOf("Nabigo ang tseke sa pag-update ng Launcher", "\uB7F0\uCC98 \uC5C5\uB370\uC774\uD2B8 \uD655\uC778 \uC2E4\uD328", "\u30E9\u30F3\u30C1\u30E3\u30FC\u306E\u66F4\u65B0\u78BA\u8A8D\u306B\u5931\u6557\u3057\u307E\u3057\u305F", "\u542F\u52A8\u5668\u66F4\u65B0\u68C0\u67E5\u5931\u8D25", "Fall\u00F3 la verificaci\u00F3n de actualizaci\u00F3n del lanzador", "Ki\u1EC3m tra c\u1EADp nh\u1EADt tr\u00ECnh kh\u1EDFi ch\u1EA1y th\u1EA5t b\u1EA1i", "Pemeriksaan pembaruan peluncur gagal", "Falha ao verificar atualiza\u00E7\u00E3o do Launcher"),
        "Launcher update failed" to arrayOf("Nabigo ang pag-update ng Launcher", "\uB7F0\uCC98 \uC5C5\uB370\uC774\uD2B8 \uC2E4\uD328", "\u30E9\u30F3\u30C1\u30E3\u30FC\u306E\u66F4\u65B0\u306B\u5931\u6557\u3057\u307E\u3057\u305F", "\u542F\u52A8\u5668\u66F4\u65B0\u5931\u8D25", "Fall\u00F3 la actualizaci\u00F3n del lanzador", "C\u1EADp nh\u1EADt tr\u00ECnh kh\u1EDFi ch\u1EA1y th\u1EA5t b\u1EA1i", "Pembaruan peluncur gagal", "Falha na atualiza\u00E7\u00E3o do Launcher"),
        "Launcher update paused" to arrayOf("Pansamantalang huminto ang pag-update ng Launcher", "\uB7F0\uCC98 \uC5C5\uB370\uC774\uD2B8 \uC77C\uC2DC \uC911\uC9C0\uB428", "\u30E9\u30F3\u30C1\u30E3\u30FC\u306E\u66F4\u65B0\u304C\u4E00\u6642\u505C\u6B62\u3055\u308C\u307E\u3057\u305F", "\u542F\u52A8\u5668\u66F4\u65B0\u5DF2\u6682\u505C", "Actualizaci\u00F3n del lanzador pausada", "C\u1EADp nh\u1EADt tr\u00ECnh kh\u1EDFi ch\u1EA1y t\u1EA1m d\u1EEBng", "Pembaruan peluncur dijeda", "Atualiza\u00E7\u00E3o do Launcher pausada"),
        "Launcher update required" to arrayOf("Kinakailangan ang pag-update ng Launcher", "\uB7F0\uCC98 \uC5C5\uB370\uC774\uD2B8 \uD544\uC694", "\u30E9\u30F3\u30C1\u30E3\u30FC\u306E\u66F4\u65B0\u304C\u5FC5\u8981\u3067\u3059", "\u542F\u52A8\u5668\u9700\u8981\u66F4\u65B0", "Se requiere actualizaci\u00F3n del lanzador", "C\u1EADp nh\u1EADt tr\u00ECnh kh\u1EDFi ch\u1EA1y l\u00E0 b\u1EAFt bu\u1ED9c", "Pembaruan peluncur diperlukan", "Atualiza\u00E7\u00E3o do Launcher necess\u00E1ria"),
        "Launcher update started" to arrayOf("Sinimulan ang pag-update ng Launcher", "\uB7F0\uCC98 \uC5C5\uB370\uC774\uD2B8 \uC2DC\uC791\uB428", "\u30E9\u30F3\u30C1\u30E3\u30FC\u306E\u66F4\u65B0\u3092\u958B\u59CB\u3057\u307E\u3057\u305F", "\u542F\u52A8\u5668\u66F4\u65B0\u5DF2\u5F00\u59CB", "Se inici\u00F3 la actualizaci\u00F3n del lanzador", "B\u1EAFt \u0111\u1EA7u c\u1EADp nh\u1EADt tr\u00ECnh kh\u1EDFi ch\u1EA1y", "Pembaruan peluncur dimulai", "Atualiza\u00E7\u00E3o do Launcher iniciada"),
        "Limited access public add-on. In-game eligibility requirements may apply." to arrayOf("Limitadong akses sa pampublikong add-on. Maaaring may mga kinakailangan sa pagiging karapat-dapat sa laro.", "\uC81C\uD55C\uB41C \uC561\uC138\uC2A4 \uACF5\uAC1C \uC560\uB4DC\uC628. \uAC8C\uC784 \uB0B4 \uC790\uACA9 \uC694\uAC74\uC774 \uC801\uC6A9\uB420 \uC218 \uC788\uC74C.", "\u5236\u9650\u4ED8\u304D\u30A2\u30AF\u30BB\u30B9\u306E\u516C\u958B\u30A2\u30C9\u30AA\u30F3\u3002\u30B2\u30FC\u30E0\u5185\u306E\u9069\u683C\u6027\u8981\u4EF6\u304C\u9069\u7528\u3055\u308C\u308B\u5834\u5408\u304C\u3042\u308A\u307E\u3059\u3002", "\u516C\u5171\u63D2\u4EF6\u8BBF\u95EE\u53D7\u9650\u3002\u53EF\u80FD\u9700\u8981\u6EE1\u8DB3\u6E38\u620F\u5185\u8D44\u683C\u8981\u6C42\u3002", "Complemento p\u00FAblico de acceso limitado. Pueden aplicarse requisitos de elegibilidad en el juego.", "Ti\u1EC7n \u00EDch b\u1ED5 sung c\u00F4ng c\u1ED9ng quy\u1EC1n h\u1EA1n h\u1EA1n ch\u1EBF. Y\u00EAu c\u1EA7u \u0111\u1EE7 \u0111i\u1EC1u ki\u1EC7n trong tr\u00F2 ch\u01A1i c\u00F3 th\u1EC3 \u00E1p d\u1EE5ng.", "Akses terbatas untuk add-on publik. Persyaratan kelayakan dalam game mungkin berlaku.", "Complemento p\u00FAblico de acesso limitado. Requisitos de elegibilidade no jogo podem se aplicar."),
        "Live launcher update report" to arrayOf("Ulat ng live na pag-update ng launcher", "\uB77C\uC774\uBE0C \uB7F0\uCC98 \uC5C5\uB370\uC774\uD2B8 \uBCF4\uACE0\uC11C", "\u30E9\u30A4\u30D6\u30E9\u30F3\u30C1\u30E3\u30FC\u66F4\u65B0\u30EC\u30DD\u30FC\u30C8", "\u5B9E\u65F6\u542F\u52A8\u5668\u66F4\u65B0\u62A5\u544A", "Informe de actualizaci\u00F3n en vivo del lanzador", "B\u00E1o c\u00E1o c\u1EADp nh\u1EADt tr\u00ECnh kh\u1EDFi ch\u1EA1y tr\u1EF1c ti\u1EBFp", "Laporan pembaruan peluncur langsung", "Relat\u00F3rio de atualiza\u00E7\u00E3o ao vivo do launcher"),
        "Load {0} more" to arrayOf("Mag-load ng {0} pa", "{0}\uAC1C \uB354 \uBD88\uB7EC\uC624\uAE30", "{0} \u4EF6\u3092\u3055\u3089\u306B\u8AAD\u307F\u8FBC\u3080", "\u52A0\u8F7D{0}\u66F4\u591A", "Cargar {0} m\u00E1s", "T\u1EA3i th\u00EAm {0}", "Memuat {0} lagi", "Carregar mais {0}"),
        "Loading the signed release notes for {0}." to arrayOf("Naglo-load ng pirmahang mga tala ng release para sa {0}.", "{0}\uC758 \uC11C\uBA85\uB41C \uB9B4\uB9AC\uC2A4 \uB178\uD2B8 \uBD88\uB7EC\uC624\uB294 \uC911", "{0} \u306E\u7F72\u540D\u6E08\u307F\u30EA\u30EA\u30FC\u30B9\u30CE\u30FC\u30C8\u3092\u8AAD\u307F\u8FBC\u307F\u4E2D", "\u6B63\u5728\u52A0\u8F7D{0}\u7684\u5DF2\u7B7E\u540D\u53D1\u5E03\u8BF4\u660E\u3002", "Cargando las notas de la versi\u00F3n firmadas para {0}.", "\u0110ang t\u1EA3i ghi ch\u00FA ph\u00E1t h\u00E0nh \u0111\u00E3 k\u00FD cho {0}.", "Memuat catatan rilis yang ditandatangani untuk {0}.", "Carregando as notas de lan\u00E7amento assinadas para {0}."),
        "Loading update details" to arrayOf("Naglo-load ng mga detalye ng pag-update", "\uC5C5\uB370\uC774\uD2B8 \uC138\uBD80 \uC815\uBCF4 \uBD88\uB7EC\uC624\uB294 \uC911", "\u66F4\u65B0\u8A73\u7D30\u3092\u8AAD\u307F\u8FBC\u307F\u4E2D", "\u6B63\u5728\u52A0\u8F7D\u66F4\u65B0\u8BE6\u60C5", "Cargando detalles de la actualizaci\u00F3n", "\u0110ang t\u1EA3i chi ti\u1EBFt c\u1EADp nh\u1EADt", "Memuat detail pembaruan", "Carregando detalhes da atualiza\u00E7\u00E3o"),
        "Loading verified update details" to arrayOf("Naglo-load ng beripikadong mga detalye ng pag-update", "\uAC80\uC99D\uB41C \uC5C5\uB370\uC774\uD2B8 \uC138\uBD80 \uC815\uBCF4 \uBD88\uB7EC\uC624\uB294 \uC911", "\u691C\u8A3C\u6E08\u307F\u306E\u66F4\u65B0\u8A73\u7D30\u3092\u8AAD\u307F\u8FBC\u307F\u4E2D", "\u6B63\u5728\u52A0\u8F7D\u5DF2\u9A8C\u8BC1\u7684\u66F4\u65B0\u8BE6\u60C5", "Cargando detalles de actualizaci\u00F3n verificados", "\u0110ang t\u1EA3i chi ti\u1EBFt c\u1EADp nh\u1EADt \u0111\u00E3 \u0111\u01B0\u1EE3c x\u00E1c minh", "Memuat detail pembaruan yang diverifikasi", "Carregando detalhes da atualiza\u00E7\u00E3o verificados"),
        "Local staged module import failed" to arrayOf("Nabigong i-import ang lokal na staged module", "\uB85C\uCEEC \uB2E8\uACC4\uBCC4 \uBAA8\uB4C8 \uAC00\uC838\uC624\uAE30 \uC2E4\uD328", "\u30ED\u30FC\u30AB\u30EB\u30B9\u30C6\u30FC\u30B8\u30E2\u30B8\u30E5\u30FC\u30EB\u306E\u30A4\u30F3\u30DD\u30FC\u30C8\u306B\u5931\u6557\u3057\u307E\u3057\u305F", "\u672C\u5730\u6682\u5B58\u6A21\u5757\u5BFC\u5165\u5931\u8D25", "Fall\u00F3 la importaci\u00F3n del m\u00F3dulo local en etapa", "Nh\u1EADp m\u00F4-\u0111un giai \u0111o\u1EA1n c\u1EE5c b\u1ED9 th\u1EA5t b\u1EA1i", "Impor modul bertahap lokal gagal", "Falha na importa\u00E7\u00E3o do m\u00F3dulo local em est\u00E1gio"),
        "Local test add-on" to arrayOf("Lokal na test add-on", "\uB85C\uCEEC \uD14C\uC2A4\uD2B8 \uC560\uB4DC\uC628", "\u30ED\u30FC\u30AB\u30EB\u30C6\u30B9\u30C8\u30A2\u30C9\u30AA\u30F3", "\u672C\u5730\u6D4B\u8BD5\u63D2\u4EF6", "Complemento de prueba local", "Ti\u1EC7n \u00EDch b\u1ED5 sung th\u1EED nghi\u1EC7m c\u1EE5c b\u1ED9", "Add-on uji lokal", "Complemento de teste local"),
        "Local test file is missing: {0}" to arrayOf("Nawawala ang lokal na test file: {0}", "\uB85C\uCEEC \uD14C\uC2A4\uD2B8 \uD30C\uC77C\uC774 \uC5C6\uC74C: {0}", "\u30ED\u30FC\u30AB\u30EB\u30C6\u30B9\u30C8\u30D5\u30A1\u30A4\u30EB\u304C\u898B\u3064\u304B\u308A\u307E\u305B\u3093: {0}", "\u672C\u5730\u6D4B\u8BD5\u6587\u4EF6\u4E22\u5931\uFF1A{0}", "El archivo de prueba local falta: {0}", "T\u1EC7p th\u1EED nghi\u1EC7m c\u1EE5c b\u1ED9 b\u1ECB thi\u1EBFu: {0}", "File uji lokal hilang: {0}", "Arquivo de teste local est\u00E1 ausente: {0}"),
        "Local test module config package does not match {0}" to arrayOf("Hindi tumutugma ang lokal na test module config package sa {0}", "\uB85C\uCEEC \uD14C\uC2A4\uD2B8 \uBAA8\uB4C8 \uAD6C\uC131 \uD328\uD0A4\uC9C0\uAC00 {0}\uC640 \uC77C\uCE58\uD558\uC9C0 \uC54A\uC74C", "\u30ED\u30FC\u30AB\u30EB\u30C6\u30B9\u30C8\u30E2\u30B8\u30E5\u30FC\u30EB\u306E\u8A2D\u5B9A\u30D1\u30C3\u30B1\u30FC\u30B8\u304C {0} \u3068\u4E00\u81F4\u3057\u307E\u305B\u3093", "\u672C\u5730\u6D4B\u8BD5\u6A21\u5757\u914D\u7F6E\u5305\u4E0E{0}\u4E0D\u5339\u914D", "El paquete de configuraci\u00F3n del m\u00F3dulo de prueba local no coincide con {0}", "G\u00F3i c\u1EA5u h\u00ECnh m\u00F4-\u0111un th\u1EED nghi\u1EC7m c\u1EE5c b\u1ED9 kh\u00F4ng kh\u1EDBp {0}", "Paket konfigurasi modul uji lokal tidak cocok dengan {0}", "Pacote de configura\u00E7\u00E3o do m\u00F3dulo de teste local n\u00E3o corresponde a {0}"),
        "Local test module is missing: {0}" to arrayOf("Nawawala ang lokal na test module: {0}", "\uB85C\uCEEC \uD14C\uC2A4\uD2B8 \uBAA8\uB4C8\uC774 \uC5C6\uC2B5\uB2C8\uB2E4: {0}", "\u30ED\u30FC\u30AB\u30EB\u30C6\u30B9\u30C8\u30E2\u30B8\u30E5\u30FC\u30EB\u304C\u898B\u3064\u304B\u308A\u307E\u305B\u3093: {0}", "\u672C\u5730\u6D4B\u8BD5\u6A21\u5757\u7F3A\u5931: {0}", "Falta el m\u00F3dulo de prueba local: {0}", "Module ki\u1EC3m tra c\u1EE5c b\u1ED9 b\u1ECB thi\u1EBFu: {0}", "Modul uji lokal hilang: {0}", "M\u00F3dulo de teste local ausente: {0}"),
        "Local test module staged" to arrayOf("Naka-prepare ang lokal na test module", "\uB85C\uCEEC \uD14C\uC2A4\uD2B8 \uBAA8\uB4C8\uC774 \uC900\uBE44\uB418\uC5C8\uC2B5\uB2C8\uB2E4", "\u30ED\u30FC\u30AB\u30EB\u30C6\u30B9\u30C8\u30E2\u30B8\u30E5\u30FC\u30EB\u304C\u30B9\u30C6\u30FC\u30B8\u30F3\u30B0\u3055\u308C\u307E\u3057\u305F", "\u672C\u5730\u6D4B\u8BD5\u6A21\u5757\u5DF2\u5206\u6279", "M\u00F3dulo de prueba local preparado", "Module ki\u1EC3m tra c\u1EE5c b\u1ED9 \u0111\u00E3 \u0111\u01B0\u1EE3c chu\u1EA9n b\u1ECB", "Modul uji lokal telah disiapkan", "M\u00F3dulo de teste local preparado"),
        "Local test package list contains an invalid package name" to arrayOf("Ang listahan ng lokal na test package ay naglalaman ng hindi wastong pangalan ng package", "\uB85C\uCEEC \uD14C\uC2A4\uD2B8 \uD328\uD0A4\uC9C0 \uBAA9\uB85D\uC5D0 \uC798\uBABB\uB41C \uD328\uD0A4\uC9C0 \uC774\uB984\uC774 \uD3EC\uD568\uB418\uC5B4 \uC788\uC2B5\uB2C8\uB2E4", "\u30ED\u30FC\u30AB\u30EB\u30C6\u30B9\u30C8\u30D1\u30C3\u30B1\u30FC\u30B8\u30EA\u30B9\u30C8\u306B\u7121\u52B9\u306A\u30D1\u30C3\u30B1\u30FC\u30B8\u540D\u304C\u542B\u307E\u308C\u3066\u3044\u307E\u3059", "\u672C\u5730\u6D4B\u8BD5\u5305\u5217\u8868\u5305\u542B\u65E0\u6548\u7684\u5305\u540D", "La lista de paquetes de prueba local contiene un nombre de paquete no v\u00E1lido", "Danh s\u00E1ch g\u00F3i ki\u1EC3m tra c\u1EE5c b\u1ED9 ch\u1EE9a t\u00EAn g\u00F3i kh\u00F4ng h\u1EE3p l\u1EC7", "Daftar paket uji lokal mengandung nama paket yang tidak valid", "A lista de pacotes de teste local cont\u00E9m um nome de pacote inv\u00E1lido"),
        "Local test package list is missing" to arrayOf("Nawawala ang listahan ng lokal na test package", "\uB85C\uCEEC \uD14C\uC2A4\uD2B8 \uD328\uD0A4\uC9C0 \uBAA9\uB85D\uC774 \uC5C6\uC2B5\uB2C8\uB2E4", "\u30ED\u30FC\u30AB\u30EB\u30C6\u30B9\u30C8\u30D1\u30C3\u30B1\u30FC\u30B8\u30EA\u30B9\u30C8\u304C\u898B\u3064\u304B\u308A\u307E\u305B\u3093", "\u672C\u5730\u6D4B\u8BD5\u5305\u5217\u8868\u7F3A\u5931", "Falta la lista de paquetes de prueba local", "Danh s\u00E1ch g\u00F3i ki\u1EC3m tra c\u1EE5c b\u1ED9 b\u1ECB thi\u1EBFu", "Daftar paket uji lokal hilang", "Lista de pacotes de teste local ausente"),
        "Local test target escaped launcher storage" to arrayOf("Nilampasan ng lokal na test target ang storage ng launcher", "\uB85C\uCEEC \uD14C\uC2A4\uD2B8 \uB300\uC0C1\uC774 \uB7F0\uCC98 \uC800\uC7A5\uC18C\uB97C \uBC97\uC5B4\uB0AC\uC2B5\uB2C8\uB2E4", "\u30ED\u30FC\u30AB\u30EB\u30C6\u30B9\u30C8\u30BF\u30FC\u30B2\u30C3\u30C8\u304C\u30E9\u30F3\u30C1\u30E3\u30FC\u306E\u30B9\u30C8\u30EC\u30FC\u30B8\u3092\u9038\u8131\u3057\u307E\u3057\u305F", "\u672C\u5730\u6D4B\u8BD5\u76EE\u6807\u8D8A\u8FC7\u542F\u52A8\u5668\u5B58\u50A8", "El objetivo de la prueba local escap\u00F3 del almacenamiento del lanzador", "M\u1EE5c ti\u00EAu ki\u1EC3m tra c\u1EE5c b\u1ED9 \u0111\u00E3 tho\u00E1t kh\u1ECFi b\u1ED9 nh\u1EDB l\u01B0u tr\u1EEF tr\u00ECnh kh\u1EDFi ch\u1EA1y", "Target uji lokal melewati penyimpanan peluncur", "Alvo de teste local escapou do armazenamento do launcher"),
        "Local test token did not match" to arrayOf("Hindi tumugma ang lokal na test token", "\uB85C\uCEEC \uD14C\uC2A4\uD2B8 \uD1A0\uD070\uC774 \uC77C\uCE58\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4", "\u30ED\u30FC\u30AB\u30EB\u30C6\u30B9\u30C8\u30C8\u30FC\u30AF\u30F3\u304C\u4E00\u81F4\u3057\u307E\u305B\u3093\u3067\u3057\u305F", "\u672C\u5730\u6D4B\u8BD5\u4EE4\u724C\u4E0D\u5339\u914D", "El token de prueba local no coincidi\u00F3", "Token ki\u1EC3m tra c\u1EE5c b\u1ED9 kh\u00F4ng kh\u1EDBp", "Token uji lokal tidak sesuai", "Token de teste local n\u00E3o correspondeu"),
        "Local test token file is missing" to arrayOf("Nawawala ang token file ng lokal na test", "\uB85C\uCEEC \uD14C\uC2A4\uD2B8 \uD1A0\uD070 \uD30C\uC77C\uC774 \uC5C6\uC2B5\uB2C8\uB2E4", "\u30ED\u30FC\u30AB\u30EB\u30C6\u30B9\u30C8\u30C8\u30FC\u30AF\u30F3\u30D5\u30A1\u30A4\u30EB\u304C\u898B\u3064\u304B\u308A\u307E\u305B\u3093", "\u672C\u5730\u6D4B\u8BD5\u4EE4\u724C\u6587\u4EF6\u7F3A\u5931", "Falta el archivo de token de prueba local", "File token ki\u1EC3m tra c\u1EE5c b\u1ED9 b\u1ECB thi\u1EBFu", "File token uji lokal hilang", "Arquivo de token de teste local ausente"),
        "Local test token is missing or invalid" to arrayOf("Nawawala o hindi wasto ang lokal na test token", "\uB85C\uCEEC \uD14C\uC2A4\uD2B8 \uD1A0\uD070\uC774 \uC5C6\uAC70\uB098 \uC798\uBABB\uB418\uC5C8\uC2B5\uB2C8\uB2E4", "\u30ED\u30FC\u30AB\u30EB\u30C6\u30B9\u30C8\u30C8\u30FC\u30AF\u30F3\u304C\u5B58\u5728\u3057\u306A\u3044\u304B\u7121\u52B9\u3067\u3059", "\u672C\u5730\u6D4B\u8BD5\u4EE4\u724C\u7F3A\u5931\u6216\u65E0\u6548", "El token de prueba local falta o es inv\u00E1lido", "Token ki\u1EC3m tra c\u1EE5c b\u1ED9 b\u1ECB thi\u1EBFu ho\u1EB7c kh\u00F4ng h\u1EE3p l\u1EC7", "Token uji lokal hilang atau tidak valid", "Token de teste local ausente ou inv\u00E1lido"),
        "Looking for a verified download that can be reused before starting the transfer." to arrayOf("Naghahanap ng beripikadong download na maaaring muling gamitin bago simulan ang paglilipat.", "\uC804\uC1A1\uC744 \uC2DC\uC791\uD558\uAE30 \uC804\uC5D0 \uC7AC\uC0AC\uC6A9\uD560 \uC218 \uC788\uB294 \uAC80\uC99D\uB41C \uB2E4\uC6B4\uB85C\uB4DC\uB97C \uCC3E\uB294 \uC911\uC785\uB2C8\uB2E4.", "\u8EE2\u9001\u3092\u958B\u59CB\u3059\u308B\u524D\u306B\u518D\u5229\u7528\u3067\u304D\u308B\u691C\u8A3C\u6E08\u307F\u306E\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u3092\u63A2\u3057\u3066\u3044\u307E\u3059\u3002", "\u5728\u5F00\u59CB\u4F20\u8F93\u524D\u67E5\u627E\u53EF\u91CD\u590D\u4F7F\u7528\u7684\u5DF2\u9A8C\u8BC1\u4E0B\u8F7D\u3002", "Buscando una descarga verificada que se pueda reutilizar antes de iniciar la transferencia.", "\u0110ang t\u00ECm m\u1ED9t b\u1EA3n t\u1EA3i xu\u1ED1ng \u0111\u00E3 \u0111\u01B0\u1EE3c x\u00E1c minh c\u00F3 th\u1EC3 t\u00E1i s\u1EED d\u1EE5ng tr\u01B0\u1EDBc khi b\u1EAFt \u0111\u1EA7u chuy\u1EC3n", "Mencari unduhan yang diverifikasi yang dapat digunakan kembali sebelum memulai transfer.", "Procurando um download verificado que possa ser reutilizado antes de iniciar a transfer\u00EAncia."),
        "Module authorization expired during transfer; renewing it once." to arrayOf("Nag-expire ang otorisasyon ng module habang naglilipat; nire-renew ito isang beses.", "\uC804\uC1A1 \uC911 \uBAA8\uB4C8 \uC778\uC99D\uC774 \uB9CC\uB8CC\uB418\uC5C8\uC2B5\uB2C8\uB2E4; \uD55C \uBC88 \uAC31\uC2E0\uD569\uB2C8\uB2E4.", "\u8EE2\u9001\u4E2D\u306B\u30E2\u30B8\u30E5\u30FC\u30EB\u306E\u8A8D\u8A3C\u304C\u671F\u9650\u5207\u308C\u306B\u306A\u308A\u307E\u3057\u305F; \u4E00\u5EA6\u66F4\u65B0\u3057\u307E\u3059\u3002", "\u4F20\u8F93\u8FC7\u7A0B\u4E2D\u6A21\u5757\u6388\u6743\u5DF2\u8FC7\u671F\uFF1B\u91CD\u65B0\u6388\u6743\u4E00\u6B21\u3002", "La autorizaci\u00F3n del m\u00F3dulo expir\u00F3 durante la transferencia; renov\u00E1ndola una vez.", "Quy\u1EC1n module h\u1EBFt h\u1EA1n trong khi chuy\u1EC3n; gia h\u1EA1n m\u1ED9t l\u1EA7n", "Otorisasi modul kadaluarsa selama transfer; memperbaruinya sekali.", "Autoriza\u00E7\u00E3o do m\u00F3dulo expirou durante a transfer\u00EAncia; renovando uma vez."),
        "No Android package was changed. You can safely try again whenever you're ready." to arrayOf("Walang binagong Android package. Maaari kang subukang muli nang ligtas anumang oras na handa ka na.", "\uBCC0\uACBD\uB41C Android \uD328\uD0A4\uC9C0\uAC00 \uC5C6\uC2B5\uB2C8\uB2E4. \uC900\uBE44\uB418\uBA74 \uC5B8\uC81C\uB4E0\uC9C0 \uB2E4\uC2DC \uC2DC\uB3C4\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "Android\u30D1\u30C3\u30B1\u30FC\u30B8\u306F\u5909\u66F4\u3055\u308C\u307E\u305B\u3093\u3067\u3057\u305F\u3002\u6E96\u5099\u304C\u3067\u304D\u305F\u3089\u3044\u3064\u3067\u3082\u518D\u8A66\u884C\u3067\u304D\u307E\u3059\u3002", "\u6CA1\u6709\u5B89\u5353\u5305\u88AB\u66F4\u6539\u3002\u60A8\u53EF\u4EE5\u5728\u51C6\u5907\u597D\u65F6\u5B89\u5168\u5730\u518D\u6B21\u5C1D\u8BD5\u3002", "No se cambi\u00F3 ning\u00FAn paquete de Android. Puedes intentarlo de nuevo con seguridad cuando est\u00E9s listo.", "Kh\u00F4ng c\u00F3 g\u00F3i Android n\u00E0o b\u1ECB thay \u0111\u1ED5i. B\u1EA1n c\u00F3 th\u1EC3 th\u1EED l\u1EA1i an to\u00E0n b\u1EA5t c\u1EE9 khi n\u00E0o s\u1EB5n s\u00E0ng", "Tidak ada paket Android yang diubah. Anda dapat mencoba lagi dengan aman kapanpun Anda siap.", "Nenhum pacote Android foi alterado. Voc\u00EA pode tentar novamente com seguran\u00E7a quando estiver pronto."),
        "No newer compatible game download" to arrayOf("Walang mas bagong compatible na game download", "\uC0C8\uB85C\uC6B4 \uD638\uD658 \uAC8C\uC784 \uB2E4\uC6B4\uB85C\uB4DC\uAC00 \uC5C6\uC2B5\uB2C8\uB2E4", "\u4E92\u63DB\u6027\u306E\u3042\u308B\u65B0\u3057\u3044\u30B2\u30FC\u30E0\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u306F\u3042\u308A\u307E\u305B\u3093", "\u6CA1\u6709\u66F4\u65B0\u7684\u517C\u5BB9\u6E38\u620F\u4E0B\u8F7D", "No hay descarga de juego compatible m\u00E1s reciente", "Kh\u00F4ng c\u00F3 b\u1EA3n t\u1EA3i game t\u01B0\u01A1ng th\u00EDch m\u1EDBi h\u01A1n", "Tidak ada unduhan permainan kompatibel yang lebih baru", "Nenhum download de jogo compat\u00EDvel mais recente"),
        "No newer version is available for this game." to arrayOf("Walang mas bagong bersyon na magagamit para sa larong ito.", "\uC774 \uAC8C\uC784\uC758 \uC0C8\uB85C\uC6B4 \uBC84\uC804\uC774 \uC5C6\uC2B5\uB2C8\uB2E4.", "\u3053\u306E\u30B2\u30FC\u30E0\u7528\u306E\u65B0\u3057\u3044\u30D0\u30FC\u30B8\u30E7\u30F3\u306F\u5229\u7528\u3067\u304D\u307E\u305B\u3093\u3002", "\u8BE5\u6E38\u620F\u6CA1\u6709\u53EF\u7528\u7684\u65B0\u7248\u672C\u3002", "No hay una versi\u00F3n m\u00E1s nueva disponible para este juego.", "Kh\u00F4ng c\u00F3 phi\u00EAn b\u1EA3n m\u1EDBi h\u01A1n n\u00E0o cho tr\u00F2 ch\u01A1i n\u00E0y", "Tidak ada versi terbaru yang tersedia untuk permainan ini.", "Nenhuma vers\u00E3o mais recente est\u00E1 dispon\u00EDvel para este jogo."),
        "Not enough free storage" to arrayOf("Kakulangan sa libreng storage", "\uC800\uC7A5 \uACF5\uAC04\uC774 \uBD80\uC871\uD569\uB2C8\uB2E4", "\u7A7A\u304D\u30B9\u30C8\u30EC\u30FC\u30B8\u304C\u4E0D\u8DB3\u3057\u3066\u3044\u307E\u3059", "\u53EF\u7528\u5B58\u50A8\u7A7A\u95F4\u4E0D\u8DB3", "No hay suficiente espacio de almacenamiento libre", "Kh\u00F4ng \u0111\u1EE7 dung l\u01B0\u1EE3ng tr\u1ED1ng", "Penyimpanan bebas tidak cukup", "Espa\u00E7o livre insuficiente"),
        "Nothing was downloaded or changed. Check again whenever you're ready." to arrayOf("Walang na-download o nabago. Suriin muli kapag handa ka na.", "\uC544\uBB34 \uAC83\uB3C4 \uB2E4\uC6B4\uB85C\uB4DC\uB418\uAC70\uB098 \uBCC0\uACBD\uB418\uC9C0 \uC54A\uC558\uC2B5\uB2C8\uB2E4. \uC900\uBE44\uAC00 \uB418\uBA74 \uB2E4\uC2DC \uD655\uC778\uD558\uC138\uC694.", "\u4F55\u3082\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u3055\u308C\u305A\u3001\u5909\u66F4\u3055\u308C\u307E\u305B\u3093\u3067\u3057\u305F\u3002\u6E96\u5099\u304C\u3067\u304D\u305F\u3089\u518D\u5EA6\u78BA\u8A8D\u3057\u3066\u304F\u3060\u3055\u3044\u3002", "\u6CA1\u6709\u4E0B\u8F7D\u6216\u66F4\u6539\u4EFB\u4F55\u5185\u5BB9\u3002\u51C6\u5907\u597D\u65F6\u8BF7\u518D\u6B21\u68C0\u67E5\u3002", "No se descarg\u00F3 ni se cambi\u00F3 nada. Verifica de nuevo cuando est\u00E9s listo.", "Kh\u00F4ng c\u00F3 g\u00EC \u0111\u01B0\u1EE3c t\u1EA3i xu\u1ED1ng ho\u1EB7c thay \u0111\u1ED5i. H\u00E3y ki\u1EC3m tra l\u1EA1i khi b\u1EA1n s\u1EB5n s\u00E0ng.", "Tidak ada yang diunduh atau diubah. Periksa kembali kapan pun Anda siap.", "Nada foi baixado ou alterado. Verifique novamente quando estiver pronto."),
        "Official game restoration required" to arrayOf("Kailangan ng opisyal na pagpapanumbalik ng laro", "\uACF5\uC2DD \uAC8C\uC784 \uBCF5\uC6D0\uC774 \uD544\uC694\uD569\uB2C8\uB2E4", "\u516C\u5F0F\u30B2\u30FC\u30E0\u306E\u5FA9\u5143\u304C\u5FC5\u8981\u3067\u3059", "\u9700\u8981\u5B98\u65B9\u6E38\u620F\u6062\u590D", "Se requiere la restauraci\u00F3n oficial del juego", "Y\u00EAu c\u1EA7u kh\u00F4i ph\u1EE5c tr\u00F2 ch\u01A1i ch\u00EDnh th\u1EE9c", "Pemulihan game resmi diperlukan", "Restaura\u00E7\u00E3o oficial do jogo necess\u00E1ria"),
        "One more step" to arrayOf("Isa pang hakbang", "\uD55C \uB2E8\uACC4 \uB354 \uC9C4\uD589", "\u3082\u3046\u4E00\u6B69\u3067\u3059", "\u8FD8\u6709\u4E00\u6B65", "Un paso m\u00E1s", "Th\u00EAm m\u1ED9t b\u01B0\u1EDBc n\u1EEFa", "Satu langkah lagi", "Mais um passo"),
        "Open Google Play on this device and search for the game." to arrayOf("Buksan ang Google Play sa cihaz na ito at hanapin ang laro.", "\uC774 \uAE30\uAE30\uC5D0\uC11C Google Play\uB97C \uC5F4\uACE0 \uAC8C\uC784\uC744 \uAC80\uC0C9\uD558\uC138\uC694.", "\u3053\u306E\u30C7\u30D0\u30A4\u30B9\u3067Google Play\u3092\u958B\u304D\u3001\u30B2\u30FC\u30E0\u3092\u691C\u7D22\u3057\u3066\u304F\u3060\u3055\u3044\u3002", "\u5728\u6B64\u8BBE\u5907\u4E0A\u6253\u5F00 Google Play \u5E76\u641C\u7D22\u6E38\u620F\u3002", "Abre Google Play en este dispositivo y busca el juego.", "M\u1EDF Google Play tr\u00EAn thi\u1EBFt b\u1ECB n\u00E0y v\u00E0 t\u00ECm tr\u00F2 ch\u01A1i.", "Buka Google Play di perangkat ini dan cari gamenya.", "Abra o Google Play neste dispositivo e pesquise o jogo."),
        "Open details after reinstalling the original game, then try again." to arrayOf("Buksan ang detalye pagkatapos muling i-install ang orihinal na laro, pagkatapos subukang muli.", "\uC6D0\uBCF8 \uAC8C\uC784\uC744 \uC7AC\uC124\uCE58\uD55C \uD6C4 \uC0C1\uC138 \uC815\uBCF4\uB97C \uC5F4\uACE0 \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uC138\uC694.", "\u5143\u306E\u30B2\u30FC\u30E0\u3092\u518D\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3057\u305F\u5F8C\u3001\u8A73\u7D30\u3092\u958B\u3044\u3066\u3001\u3082\u3046\u4E00\u5EA6\u8A66\u3057\u3066\u304F\u3060\u3055\u3044\u3002", "\u91CD\u65B0\u5B89\u88C5\u539F\u59CB\u6E38\u620F\u540E\u6253\u5F00\u8BE6\u60C5\uFF0C\u7136\u540E\u518D\u8BD5\u4E00\u6B21\u3002", "Abre los detalles despu\u00E9s de reinstalar el juego original, luego intenta de nuevo.", "M\u1EDF chi ti\u1EBFt sau khi c\u00E0i \u0111\u1EB7t l\u1EA1i tr\u00F2 ch\u01A1i g\u1ED1c, sau \u0111\u00F3 th\u1EED l\u1EA1i.", "Buka detail setelah menginstal ulang game asli, lalu coba lagi.", "Abra os detalhes ap\u00F3s reinstalar o jogo original e tente novamente."),
        "Open in browser" to arrayOf("Buksan sa browser", "\uBE0C\uB77C\uC6B0\uC800\uC5D0\uC11C \uC5F4\uAE30", "\u30D6\u30E9\u30A6\u30B6\u3067\u958B\u304F", "\u5728\u6D4F\u89C8\u5668\u4E2D\u6253\u5F00", "Abrir en el navegador", "M\u1EDF trong tr\u00ECnh duy\u1EC7t", "Buka di browser", "Abrir no navegador"),
        "Opening Android installer" to arrayOf("Binubuksan ang Android installer", "Android \uC124\uCE58 \uD504\uB85C\uADF8\uB7A8 \uC5F4\uAE30", "Android\u30A4\u30F3\u30B9\u30C8\u30FC\u30E9\u30FC\u3092\u958B\u3044\u3066\u3044\u307E\u3059", "\u6B63\u5728\u6253\u5F00 Android \u5B89\u88C5\u7A0B\u5E8F", "Abriendo instalador de Android", "\u0110ang m\u1EDF tr\u00ECnh c\u00E0i \u0111\u1EB7t Android", "Membuka pemasang Android", "Abrindo instalador do Android"),
        "Opening game" to arrayOf("Binubuksan ang laro", "\uAC8C\uC784 \uC5F4\uAE30", "\u30B2\u30FC\u30E0\u3092\u958B\u3044\u3066\u3044\u307E\u3059", "\u6B63\u5728\u6253\u5F00\u6E38\u620F", "Abriendo juego", "\u0110ang m\u1EDF tr\u00F2 ch\u01A1i", "Membuka game", "Abrindo jogo"),
    )
}
